'use strict';

const { Benchmark } = require('benchmark');

const stream = {
    write() {
        // nothing to do
    },
};

const kroniko = require('kroniko');
kroniko.install({
    std: {
        format: 'line',
        stream: {
            stdout: stream,
            stderr: stream,
        },
    },
});

const lineStream = require('../streams/line')({ // eslint-disable-line
    stream,
    template: '{{levelName}} {{msg}}{{#data}}\n{{data}}{{/data}}{{#err}}\n{{err.stack}}{{/err}}',
});

const bunyan = require('bunyan').createLogger({
    name: 'bunyan',
    streams: [
        {
            level: 'info',
            type: 'raw',
            stream: {
                write(data) {
                    data.levelName = 'INFO';
                    lineStream.write(data);
                },
            },
        },
    ],
});

const pino = require('pino')({}, {
    write(line) {
        let data = JSON.parse(line);
        data.levelName = 'INFO';
        lineStream.write(data);
    },
});

const yandexLogger = require('../src')({
    name: 'yandex-logger',
    middleware: [
        // отключаем все стандартные мидлвары
    ],
    streams: [
        {
            level: 'info',
            stream: lineStream,
        },
    ],
});

const data = {
    x: 1,
    y: 2,
    z: {
        x: 1,
        y: 2,
        z: [1, 2],
    },
};
const message = 'Something bad!';
const err = new TypeError('undefined is not a function');

let suite = new Benchmark.Suite('Logger');
suite
    .add('[yandex-logger] Simple message', () => {
        yandexLogger.info(message);
    })
    .add('[bunyan] Simple message', () => {
        bunyan.info(message);
    })
    .add('[pino] Simple message', () => {
        pino.info(message);
    })
    .add('[kroniko] Simple message', () => {
        kroniko.info(message);
    })
    .add('[yandex-logger] Message and data', () => {
        yandexLogger.info({ data }, message);
    })
    .add('[bunyan] Message and data', () => {
        bunyan.info({ data }, message);
    })
    .add('[pino] Message and data', () => {
        pino.info({ data }, message);
    })
    .add('[kroniko] Message and data', () => {
        kroniko.info(message, data);
    })
    .add('[yandex-logger] Error', () => {
        yandexLogger.error(err);
    })
    .add('[bunyan] Error', () => {
        bunyan.error(err);
    })
    .add('[pino] Error', () => {
        pino.error(err);
    })
    .add('[kroniko] Error', () => {
        kroniko.error(err);
    })
    .on('cycle', event => console.warn(String(event.target)))
    .on('error', err => console.warn('Ошибка!', err))
    .run();
